B.ai2=new A.bw("Ch\u01b0a c\xf3 y\xeau c\u1ea7u thanh to\xe1n.",B.K,null)
B.ai3=new A.bw("Ch\u1ec9 chia s\u1ebb m\xe3 v\u1edbi ng\u01b0\u1eddi c\xf9ng nh\xf3m. T\u1ea1o m\xe3 m\u1edbi s\u1ebd thay th\u1ebf m\xe3 c\u0169; th\xe0nh vi\xean nh\u1eadp m\xe3 trong m\u1ee5c D\u1ecbch v\u1ee5 c\u1ee7a t\xf4i.",B.K,null)
B.ai4=new A.bw("B\u1ea1n ch\u01b0a th\u1ef1c hi\u1ec7n \u0111\u01a1n \u0111\u1eb7t mua n\xe0o.",B.K,null)
B.ai5=new A.bw("Hi\u1ec7n v\u1eadt ch\u01b0a c\xf3 b\u1ea3n thuy\u1ebft minh \u0111\u01b0\u1ee3c xu\u1ea5t b\u1ea3n.",B.K,null)
B.ai6=new A.bw("B\u1ea1n ch\u01b0a l\u01b0u h\xe0nh tr\xecnh c\xe1 nh\xe2n n\xe0o.",B.K,null)
