B.aic=new A.bw("C\xe0i \u0111\u1eb7t v\xe0 d\u1eef li\u1ec7u ch\u1ec9 \u0111\u01b0\u1ee3c gi\u1eef trong phi\xean tr\u1ea3i nghi\u1ec7m hi\u1ec7n t\u1ea1i.",B.K,null)
B.aid=new A.bw("Gi\u01a1 camera v\u1ec1 ph\xeda hi\u1ec7n v\u1eadt t\u1ea1i t\u1ee7 tr\u01b0ng b\xe0y \u0111\u1ec3 ch\u1ee5p v\xe0 nh\u1eadn di\u1ec7n th\xf4ng minh, ho\u1eb7c t\u1ea3i \u1ea3nh c\xf3 s\u1eb5n t\u1eeb th\u01b0 vi\u1ec7n.",B.K,null)
B.aie=new A.bw("Ch\u01b0a c\xf3 b\u1ea3o t\xe0ng. H\xe3y t\u1ea3i l\u1ea1i danh m\u1ee5c ho\u1eb7c li\xean h\u1ec7 nh\xe2n vi\xean.",B.K,null)
B.aif=new A.bw("Xem hi\u1ec7n v\u1eadt n\u1eb1m \u1edf ph\xf2ng v\xe0 t\u1ea7ng n\xe0o. Qu\xe9t QR t\u1ea1i v\u1ecb tr\xed \u0111ang \u0111\u1ee9ng \u0111\u1ec3 t\xecm \u0111\u01b0\u1eddng tr\xean s\u01a1 \u0111\u1ed3.",B.K,null)
B.aig=new A.bw("H\u1ecfi v\u1ec1 hi\u1ec7n v\u1eadt \u0111ang xem. Tr\u1ee3 l\xfd tham kh\u1ea3o n\u1ed9i dung ti\u1ebfng Vi\u1ec7t \u0111\xe3 \u0111\u01b0\u1ee3c b\u1ea3o t\xe0ng xu\u1ea5t b\u1ea3n.",B.K,null)
B.aih=new A.bw("L\u01b0\u1ee3t tham quan t\u1ef1 do. Qu\xe9t QR t\u1ea1i hi\u1ec7n v\u1eadt \u0111\u1ec3 ghi nh\u1eadn kh\xe1m ph\xe1.",B.K,null)
B.aii=new A.bw("Ch\u01b0a c\xf3 n\u1ed9i dung c\u1ee7a g\xf3i.",B.K,null)
