B.aik=new A.bw("M\u1edf \u1ee9ng d\u1ee5ng ng\xe2n h\xe0ng b\u1ea5t k\u1ef3 \u0111\u1ec3 qu\xe9t m\xe3 QR, ho\u1eb7c sao ch\xe9p ch\xednh x\xe1c s\u1ed1 t\xe0i kho\u1ea3n v\xe0 n\u1ed9i dung chuy\u1ec3n kho\u1ea3n tr\xean.",B.K,null)
B.ail=new A.bw("B\u1ea1n c\xf3 th\u1ec3 tra c\u1ee9u b\u1ed9 s\u01b0u t\u1eadp m\xe0 kh\xf4ng c\u1ea7n c\u1ea5p quy\u1ec1n m\xe1y \u1ea3nh.",B.K,null)
